import React, { Component } from 'react';

class Home extends Component {
  render() {
    return (
      <div style={{ textAlign: 'center', marginTop: '30px' }}>
        <h2>ADMIN DASHBOARD</h2>
        <p>Chào mừng bạn đến với trang quản trị hệ thống QR-Menu!</p>
      </div>
    );
  }
}

export default Home;
